import React, { useState, useRef } from 'react';
import PromotionItem from './PromotionItem';
import '../styles/ProductsCarousel.css';

const ProductsCarousel = () => {
    const [position, setPosition] = useState(0);
    const carouselRef = useRef(null);
    
    const products = [
        { id: 1, title: 'Крісло офісне', img: `${process.env.PUBLIC_URL}/imgg/Frame 12.png`, rating: 4.2, price: 5999, oldPrice: 7999, discount: 25 },
        { id: 2, title: 'Шафа для одягу', img: `${process.env.PUBLIC_URL}/imgg/Frame 11.png`, rating: 4.7, price: 9999, oldPrice: 12999, discount: 23 },
        { id: 3, title: 'Кухонний гарнітур', img: `${process.env.PUBLIC_URL}/imgg/Frame 14.png`, rating: 4.3, price: 19999, oldPrice: 24999, discount: 20 },
        { id: 4, title: 'Дзеркало в ванну', img: `${process.env.PUBLIC_URL}/imgg/Frame 10.png`, rating: 4.9, price: 2999, oldPrice: 3999, discount: 25 },
        { id: 5, title: 'Стілець барний', img: `${process.env.PUBLIC_URL}/imgg/Frame 13.png`, rating: 3.8, price: 1990, oldPrice: 2490, discount: 20 },
        { id: 6, title: 'Комод дерев\'яний', img: `${process.env.PUBLIC_URL}/imgg/Frame 15.png`, rating: 4.4, price: 6990, oldPrice: 8990, discount: 22 }
    ];

    const handlePrev = () => {
        if (position < 0) {
            setPosition(position + 1);
        }
    };

    const handleNext = () => {
        const maxPosition = -(products.length - 4);
        if (position > maxPosition) {
            setPosition(position - 1);
        }
    };

    return (
        <section className="products-carousel-section">
            <div className="products-carousel-header">
                <h2>Акції</h2>
                <a href="#" className="all-btn">Усе</a>
            </div>
            <div className="products-carousel-container">
                <div
                    className="products-carousel-track"
                    ref={carouselRef}
                    style={{ transform: `translateX(${position * 100}%)` }}
                >
                    {products.map(product => (
                        <div key={product.id} className="products-carousel-item">
                            <PromotionItem item={product} />
                        </div>
                    ))}
                </div>
                <div className="products-carousel-nav">
                    <button onClick={handlePrev}>&lt;</button>
                    <button onClick={handleNext}>&gt;</button>
                </div>
            </div>
        </section>
    );
};

export default ProductsCarousel;
